-- Questoes autorais adicionais de Direito (lote 6): 100 questoes variadas.

alter table public.questions add column if not exists banca text;
alter table public.questions add column if not exists concurso text;
create index if not exists questions_banca_concurso_idx on public.questions (banca, concurso);

insert into public.questions (subject_id, source_ref, prompt, options, correct_index, explanation, difficulty, topic, question_type, status, sort_order, banca, concurso)
values
-- Constitucional
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-156', 'A Constituicao Federal de 1988 adota como forma de Estado:', '["Estado unitario.","Estado federal.","Estado confederativo.","Estado monarquico.","Estado socialista."]'::jsonb, 1, 'A Constituicao de 1988 adota o Estado federal, com uniao indissolvel de Estados, Municipios e Distrito Federal.', 'easy', 'Forma de Estado', 'multiple_choice', 'published', 5225, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-157', 'Os direitos fundamentais na Constituicao podem ser classificados como:', '["Apenas individuais.","Individuais, coletivos, sociais, de nacionalidade, politicos e de cidadania.","Somente sociais.","Apenas politicos.","Somente coletivos."]'::jsonb, 1, 'A Constituicao reconhece direitos individuais, coletivos, sociais, de nacionalidade, politicos e de cidadania.', 'medium', 'Direitos fundamentais', 'multiple_choice', 'published', 5226, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-158', 'O controle de constitucionalidade no Brasil pode ser:', '["Apenas preventivo e concentrado.","Difuso e concentrado, acao ou defesa, conforme o caso.","Apenas judicial e abstrato.","Somente legislativo.","Apenas administrativo."]'::jsonb, 1, 'O controle pode ser difuso (incidental) ou concentrado (abstrato), alem de preventivo ou repressivo, conforme o caso.', 'medium', 'Controle de constitucionalidade', 'multiple_choice', 'published', 5227, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-159', 'O principio da separacao dos Poderes implica:', '["Concentracao de funcoes em um unico orgao.","Divisao e equilibrio entre Executivo, Legislativo e Judiciario.","Subordinacao do Judiciario ao Executivo.","Ausencia de freios e contrapesos.","Supremacia do Legislativo."]'::jsonb, 1, 'A separacao dos Poderes divide e equilibra as funcoes entre os tres Poderes, com freios e contrapesos.', 'easy', 'Separacao dos Poderes', 'multiple_choice', 'published', 5228, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-160', 'A emenda constitucional exige, em regra:', '["Maioria simples em turno unico.","Tres quintos dos votos dos membros de cada Casa, em dois turnos.","Unanimidade.","Referendo popular obrigatorio.","Sancao presidencial."]'::jsonb, 1, 'A emenda constitucional exige aprovacao por tres quintos dos membros de cada Casa do Congresso, em dois turnos.', 'medium', 'Poder constituinte derivado', 'multiple_choice', 'published', 5229, 'CEBRASPE', 'Tribunais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-161', 'O mandado de seguranca coletivo pode ser impetrado por:', '["Qualquer cidadao.","Partido politico, organizacao sindical, associacao ou entidade de classe, em defesa de seus membros.","Apenas o Ministerio Publico.","Somente o Defensor Publico.","Apenas o Presidente."]'::jsonb, 1, 'O mandado de seguranca coletivo pode ser impetrado por partido, sindicato, associacao ou entidade de classe, em defesa de direitos de seus membros.', 'medium', 'Remedios constitucionais', 'multiple_choice', 'published', 5230, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-162', 'A intervencao federal nos Estados pode ocorrer, entre outras hipoteses:', '["Apenas por decisao judicial.","Para garantir a lei federal, a ordem publica ou a execucao de ordem judicial, conforme a Constituicao.","Por vontade do Presidente, sem fundamento.","Somente em caso de guerra.","Apenas por solicitacao do Governador."]'::jsonb, 1, 'A intervencao federal pode ocorrer para garantir a lei federal, a ordem publica ou a execucao de ordem judicial, entre outras.', 'medium', 'Intervencao federal', 'multiple_choice', 'published', 5231, 'FGV', 'Tribunais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-163', 'A liberdade de expressao, na Constituicao, e:', '["Absoluta, sem qualquer limitacao.","Garantida, com as restricoes previstas na propria Constituicao.","Condicionada a autorizacao previa.","Limitada a jornalistas.","Exclusiva de partidos politicos."]'::jsonb, 1, 'A liberdade de expressao e garantida, com as restricoes expressas na Constituicao (como anonimato e propaganda de guerra).', 'medium', 'Direitos fundamentais: liberdade de expressao', 'multiple_choice', 'published', 5232, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-164', 'O principio da legalidade, aplicado a administracao publica, significa que:', '["A administracao pode fazer tudo que a lei nao proibe.","A administracao so pode fazer o que a lei autoriza.","A lei e mera sugestao.","O administrador tem poder discricionario ilimitado.","A administracao pode ignorar a lei por conveniencia."]'::jsonb, 1, 'Pela legalidade, a administracao so pode atuar conforme autorizacao legal.', 'easy', 'Principio da legalidade', 'multiple_choice', 'published', 5233, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-165', 'O devido processo legal, na Constituicao, abrange:', '["Apenas o processo penal.","O conjunto de garantias processuais em todas as esferas.","Somente o processo civil.","Apenas a fase de instrucao.","Somente a sentenca."]'::jsonb, 1, 'O devido processo legal abrange garantias processuais em todas as esferas, civil, penal e administrativa.', 'medium', 'Devido processo legal', 'multiple_choice', 'published', 5234, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-166', 'A acao popular pode ser proposta por:', '["Qualquer cidadao, no exercicio dos direitos politicos.","Apenas o Ministerio Publico.","Somente partidos politicos.","Apenas o Defensor Publico.","Somente o Presidente."]'::jsonb, 0, 'A acao popular pode ser proposta por qualquer cidadao no exercicio dos direitos politicos.', 'medium', 'Acao popular', 'multiple_choice', 'published', 5235, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-constitucional'), 'LAW-AUTH-167', 'A nacionalidade brasileira pode ser originaria ou:', '["Naturalizada.","Temporaria.","Provisoria.","Condicional.","Suspensa."]'::jsonb, 0, 'A nacionalidade pode ser originaria (natos) ou adquirida (naturalizados).', 'easy', 'Nacionalidade', 'multiple_choice', 'published', 5236, 'VUNESP', 'OAB'),
-- Penal
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-168', 'O principio da humanidade das penas exige:', '["Penas cruéis e degradantes.","Penas compativeis com a dignidade humana.","Prisao perpetua.","Trabalho forcado.","Isolamento total."]'::jsonb, 1, 'O principio da humanidade veda penas cruéis, degradantes ou incompativeis com a dignidade humana.', 'easy', 'Principios penais', 'multiple_choice', 'published', 5237, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-169', 'A tentativa e punivel quando:', '["O crime e impossivel.","O agente inicia a execucao e nao se consuma por circunstancias alheias a sua vontade.","O agente desiste voluntariamente.","O crime e de acao penal privada.","O agente tem menos de 18 anos."]'::jsonb, 1, 'A tentativa e punivel quando o agente inicia a execucao e o crime nao se consuma por circunstancias alheias a sua vontade.', 'medium', 'Tentativa', 'multiple_choice', 'published', 5238, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-170', 'O erro de proibicao, quando inevitavel, pode:', '["Aumentar a pena.","Excluir a culpabilidade.","Transformar o crime em contravencao.","Gerar prisao perpetua.","Substituir a lei."]'::jsonb, 1, 'O erro de proibicao inevitavel exclui a culpabilidade.', 'medium', 'Erro de proibicao', 'multiple_choice', 'published', 5239, 'FGV', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-171', 'A legítima defesa exige, entre outros requisitos:', '["Agressao futura e possivel.","Agressao injusta, atual ou iminente, e uso moderado dos meios necessarios.","Agressao justa e proporcional.","Ausencia de perigo.","Uso de qualquer meio."]'::jsonb, 1, 'A legítima defesa exige agressao injusta, atual ou iminente, e uso moderado dos meios necessarios.', 'medium', 'Legitima defesa', 'multiple_choice', 'published', 5240, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-172', 'O estado de necessidade exige:', '["Perigo atual a direito proprio ou de terceiro, sem dever legal de enfrentar o perigo.","Perigo futuro e hipotetico.","Agressao injusta de terceiro.","Culpa do agente.","Dolo eventual."]'::jsonb, 0, 'O estado de necessidade exige perigo atual a direito proprio ou de terceiro, sem dever legal de enfrentar o perigo.', 'medium', 'Estado de necessidade', 'multiple_choice', 'published', 5241, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-173', 'A coautoria, no concurso de pessoas, ocorre quando:', '["Apenas um executa e outro auxilia.","Dois ou mais agentes praticam o crime em colaboracao, com dominio do fato.","Um apenas planeja, sem participar.","O agente e menor de 18 anos.","O crime e de acao penal privada."]'::jsonb, 1, 'A coautoria ocorre quando dois ou mais agentes praticam o crime em colaboracao, com dominio do fato.', 'medium', 'Concurso de pessoas', 'multiple_choice', 'published', 5242, 'FCC', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-174', 'A reincidencia, para fins penais, ocorre quando:', '["O agente comete novo crime apos transito em julgado de condenacao anterior.","O agente e processado novamente.","O agente e indiciado novamente.","O agente comete crime antes da sentenca.","O agente e absolvido."]'::jsonb, 0, 'A reincidencia ocorre quando o agente comete novo crime apos transito em julgado de condenacao anterior.', 'medium', 'Reincidencia', 'multiple_choice', 'published', 5243, 'FGV', 'Tribunais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-175', 'A prescricao da pretensao punitiva, em regra:', '["Nao se aplica aos crimes hediondos.","Extingue a punibilidade pelo decurso do prazo legal.","Suspende automaticamente o processo.","Interrompe a execucao da pena.","Aumenta a pena."]'::jsonb, 1, 'A prescricao da pretensao punitiva extingue a punibilidade pelo decurso do prazo legal.', 'medium', 'Prescricao', 'multiple_choice', 'published', 5244, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-176', 'O principio da insignificancia pode afastar a tipicidade quando:', '["O fato e grave.","O bem juridico e de alto valor.","A lesao e minima e o comportamento e socialmente irrelevante.","O agente e reincidente.","O crime e hediondo."]'::jsonb, 2, 'O principio da insignificancia afasta a tipicidade quando a lesao e minima e o comportamento e socialmente irrelevante.', 'medium', 'Principio da insignificancia', 'multiple_choice', 'published', 5245, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-177', 'A desistência voluntaria, no crime tentado, resulta em:', '["Punicao pela tentativa.","Nao ha punicao pelo crime tentado, mas respondem-se pelos atos ja praticados.","Extincao automatica da punibilidade.","Condenacao pelo resultado consumado.","Suspensao do processo."]'::jsonb, 1, 'Na desistencia voluntaria, nao ha punicao pelo crime tentado, mas o agente responde pelos atos ja praticados.', 'medium', 'Desistencia voluntaria', 'multiple_choice', 'published', 5246, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-178', 'O crime impossivel ocorre quando:', '["O agente nao inicia a execucao.","O meio utilizado e ineficaz para produzir o resultado.","O agente desiste voluntariamente.","O resultado ocorre.","O crime e de acao penal privada."]'::jsonb, 1, 'O crime impossivel ocorre quando o meio utilizado e ineficaz para produzir o resultado.', 'medium', 'Crime impossivel', 'multiple_choice', 'published', 5247, 'FGV', 'Tribunais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-179', 'A culpabilidade pressupoe:', '["Apenas o resultado.","Capacidade, consciencia da ilicitude e exigibilidade de conduta diversa.","Apenas o dolo.","Apenas a culpa.","Apenas a tipicidade."]'::jsonb, 1, 'A culpabilidade pressupoe capacidade, consciencia da ilicitude e exigibilidade de conduta diversa.', 'medium', 'Culpabilidade', 'multiple_choice', 'published', 5248, 'VUNESP', 'OAB'),
-- Civil
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-180', 'A boa-fe objetiva, no Codigo Civil, impoe as partes:', '["Apenas o cumprimento do contrato.","Padroes de lealdade, cooperacao e confianca.","A renuncia a direitos.","A subordinacao ao credor.","A execucao forcada."]'::jsonb, 1, 'A boa-fe objetiva impoe padroes de lealdade, cooperacao e confianca nas relacoes contratuais.', 'easy', 'Boa-fe objetiva', 'multiple_choice', 'published', 5249, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-181', 'A responsabilidade civil objetiva dispensa a prova de:', '["Dano e nexo causal.","Culpa do agente.","Existencia do fato.","Contrato.","Legitimidade."]'::jsonb, 1, 'Na responsabilidade objetiva, dispensa-se a prova de culpa, mas mantem-se dano e nexo causal.', 'medium', 'Responsabilidade civil', 'multiple_choice', 'published', 5250, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-182', 'A prescricao, em regra, extingue:', '["O direito.","A pretensao.","O fato juridico.","O contrato.","A obrigacao natural."]'::jsonb, 1, 'A prescricao extingue a pretensao, nao o direito.', 'medium', 'Prescricao e Decadencia', 'multiple_choice', 'published', 5251, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-183', 'A decadencia, em regra, extingue:', '["A pretensao.","O direito potestativo.","O contrato.","A obrigacao natural.","A responsabilidade."]'::jsonb, 1, 'A decadencia extingue o direito potestativo pelo nao exercicio no prazo.', 'medium', 'Prescricao e Decadencia', 'multiple_choice', 'published', 5252, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-184', 'O contrato de compra e venda, em regra, transfere:', '["Apenas a posse.","A propriedade, com as obrigacoes de entregar e pagar.","Apenas o risco.","Apenas a propriedade, sem obrigacoes.","Apenas o uso."]'::jsonb, 1, 'O contrato de compra e venda transfere a propriedade, com obrigacoes de entregar e pagar.', 'medium', 'Contratos em Especie', 'multiple_choice', 'published', 5253, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-185', 'A locacao de imovel, em regra, exige:', '["Apenas contrato verbal.","Contrato escrito, com duracao e valor, conforme a lei.","Autorizacao judicial.","Registro no cartorio, sempre.","Pagamento antecipado."]'::jsonb, 1, 'A locacao de imovel exige contrato, com duracao e valor, conforme a lei de locacoes.', 'medium', 'Contratos em Especie', 'multiple_choice', 'published', 5254, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-186', 'O mandato, no Codigo Civil, e:', '["Um contrato de trabalho.","Um contrato pelo qual uma pessoa confia a outra a pratica de atos ou a gestao de negocios.","Um contrato de prestacao de servicos.","Um contrato de sociedade.","Um contrato de deposito."]'::jsonb, 1, 'O mandato e contrato pelo qual uma pessoa confia a outra a pratica de atos ou a gestao de negocios.', 'medium', 'Contratos em Especie', 'multiple_choice', 'published', 5255, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-187', 'A fianca, no Codigo Civil, e:', '["Uma garantia real.","Uma garantia pessoal, acessoria a obrigacao principal.","Um contrato de seguro.","Um deposito.","Uma novacao."]'::jsonb, 1, 'A fianca e garantia pessoal, acessoria a obrigacao principal.', 'medium', 'Contratos em Especie', 'multiple_choice', 'published', 5256, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-188', 'O usufruto, como direito real em coisa alheia, confere ao usufrutuario:', '["A propriedade do bem.","O direito de usar e perceber os frutos, conservando a substancia do bem.","Apenas o uso, sem frutos.","Apenas a habitacao.","A posse exclusiva."]'::jsonb, 1, 'O usufruto confere o direito de usar e perceber os frutos, conservando a substancia do bem.', 'medium', 'Direitos Reais em Coisa Alheia', 'multiple_choice', 'published', 5257, 'CEBRASPE', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-189', 'A servidao, como direito real em coisa alheia, e:', '["A posse do bem serviente.","Uma carga imposta a um imovel em beneficio de outro.","A propriedade do imovel dominante.","Um contrato de locacao.","Uma garantia real."]'::jsonb, 1, 'A servidao e uma carga imposta a um imovel (serviente) em beneficio de outro (dominante).', 'medium', 'Direitos Reais em Coisa Alheia', 'multiple_choice', 'published', 5258, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-190', 'A adocao, no Codigo Civil, exige:', '["Apenas acordo entre os pais.","Autorizacao judicial, com avaliacao da situacao da crianca e dos adotantes.","Apenas registro em cartorio.","Consentimento da crianca, sempre.","Autorizacao do Ministerio Publico, apenas."]'::jsonb, 1, 'A adocao exige autorizacao judicial, com avaliacao da situacao da crianca e dos adotantes.', 'medium', 'Filiacao, Reconhecimento dos Filhos, Adocao e Guarda', 'multiple_choice', 'published', 5259, 'FGV', 'OAB'),
((select id from public.subjects where slug='direito-civil'), 'LAW-AUTH-191', 'A guarda de menor pode ser:', '["Apenas unilateral.","Compartilhada ou unilateral, conforme o caso.","Apenas do Estado.","Apenas dos avos.","Sempre do pai."]'::jsonb, 1, 'A guarda pode ser compartilhada ou unilateral, conforme o interesse da crianca.', 'medium', 'Filiacao, Reconhecimento dos Filhos, Adocao e Guarda', 'multiple_choice', 'published', 5260, 'VUNESP', 'Tribunais'),
-- Penal mais
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-192', 'O dolo, no direito penal, e:', '["A culpa grave.","A vontade e a consciencia de realizar o tipo penal.","A negligencia.","A imprudencia.","A inobservancia de lei."]'::jsonb, 1, 'O dolo e a vontade e a consciencia de realizar o tipo penal.', 'easy', 'Dolo e culpa', 'multiple_choice', 'published', 5261, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-193', 'A culpa, no direito penal, pode ser:', '["Apenas dolosa.","Imprudencia, negligencia ou impericia.","Apenas intencional.","Apenas eventual.","Apenas preterdolosa."]'::jsonb, 1, 'A culpa penal se manifesta por imprudencia, negligencia ou impericia.', 'easy', 'Dolo e culpa', 'multiple_choice', 'published', 5262, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-194', 'A extincao da punibilidade pode ocorrer por:', '["Apenas por prescricao.","Morte do agente, anistia, graca, indulto, abolicao do crime, entre outros.","Somente por anistia.","Apenas por graca.","Somente por indulto."]'::jsonb, 1, 'A punibilidade se extingue por morte, anistia, graca, indulto, abolicao do crime, entre outros.', 'medium', 'Extincao da punibilidade', 'multiple_choice', 'published', 5263, 'FGV', 'Tribunais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-195', 'A medida de seguranca, no direito penal, aplica-se a:', '["Apenas reus primarios.","Inimputavel ou semi-imputavel, conforme o caso.","Apenas reus reincidentes.","Apenas menores de 18 anos.","Apenas estrangeiros."]'::jsonb, 1, 'A medida de seguranca aplica-se a inimputavel ou semi-imputavel.', 'medium', 'Medida de seguranca', 'multiple_choice', 'published', 5264, 'VUNESP', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-196', 'O crime continuado ocorre quando:', '["O agente comete crimes independentes.","O agente, mediante mais de uma acao ou omissao, pratica crimes da mesma especie em condicoes de tempo, lugar e modalidade semelhantes.","O agente comete um unico crime.","O agente desiste.","O crime e impossivel."]'::jsonb, 1, 'O crime continuado ocorre quando o agente pratica crimes da mesma especie em condicoes semelhantes.', 'medium', 'Crime continuado', 'multiple_choice', 'published', 5265, 'CEBRASPE', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-197', 'A tentativa, no Codigo Penal, e punida:', '["Com a pena do crime consumado, integralmente.","Com a pena do crime consumado, reduzida de um a dois tercos.","Sem reducao alguma.","Com a pena minima apenas.","Com a pena maxima."]'::jsonb, 1, 'A tentativa e punida com a pena do crime consumado, reduzida de um a dois tercos.', 'medium', 'Tentativa', 'multiple_choice', 'published', 5266, 'FCC', 'OAB'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-198', 'A maioridade penal, no Brasil, e aos:', '["16 anos.","18 anos.","21 anos.","14 anos.","20 anos."]'::jsonb, 1, 'A maioridade penal no Brasil e aos 18 anos.', 'easy', 'Imputabilidade', 'multiple_choice', 'published', 5267, 'FGV', 'Carreiras policiais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-199', 'O principio da legalidade penal veda:', '["A analogia em favor do reu.","A analogia em desfavor do reu.","A interpretacao extensiva em favor do reu.","A lei penal mais benéfica.","A retroatividade benéfica."]'::jsonb, 1, 'A legalidade penal veda a analogia em desfavor do reu.', 'easy', 'Principio da legalidade penal', 'multiple_choice', 'published', 5268, 'VUNESP', 'Tribunais'),
((select id from public.subjects where slug='direito-penal'), 'LAW-AUTH-200', 'O crime omissivo proprio ocorre quando:', '["O agente pratica acao tipica.","A norma penal descreve a omissao como crime.","O agente tem dever de garantidor.","O resultado e causado por terceiro.","O agente age com dolo."]'::jsonb, 1, 'O crime omissivo proprio ocorre quando a norma penal descreve a omissao como crime.', 'medium', 'Crime omissivo', 'multiple_choice', 'published', 5269, 'CEBRASPE', 'OAB'),
-- Processo Civil
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-201', 'A competencia absoluta, em regra:', '["Pode ser prorrogada por acordo.","Nao pode ser prorrogada, e a nulidade pode ser alegada a qualquer tempo.","Depende de alegacao da parte.","Pode ser alterada por convencao.","E definida apenas pelo valor da causa."]'::jsonb, 1, 'A competencia absoluta nao pode ser prorrogada e a nulidade pode ser alegada a qualquer tempo.', 'medium', 'Competencia', 'multiple_choice', 'published', 5270, 'FCC', 'Tribunais'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-202', 'A tutela de evidencia, no CPC, pode ser concedida quando:', '["Houver apenas pedido do autor.","O direito for incontroverso e a prova for documental suficiente.","Houver litigio complexo.","Apenas em acoes de familia.","Houver necessidade de pericia."]'::jsonb, 1, 'A tutela de evidencia pode ser concedida quando o direito for incontroverso e a prova for documental suficiente.', 'medium', 'Tutela provisoria', 'multiple_choice', 'published', 5271, 'FGV', 'OAB'),
((select id from public.subjects where slug='processo-civil'), 'LAW-AUTH-203', 'A coisa julgada formal ocorre quando:', '["A sentenca transita em julgado.","A sentenca nao esta mais sujeita a recurso ordinario, mas pode ser alterada por recurso extraordinario.","A sentenca e proferida.","A sentenca e publicada.","A sentenca e executada."]'::jsonb, 1, 'A coisa julgada formal ocorre quando a decisao nao esta mais sujeita a recurso ordinario.', 'medium', 'Coisa julgada', 'multiple_choice', 'published', 5272, 'VUNESP', 'Tribunais'),
